export function selectedPower(settings,id){return POWERUPS[id]?.find(p=>p.id===settings?.powerups?.[id])||POWERUPS[id]?.[0]||null;}
export function canChoosePower(app){return !app.playing||!!app.scene?.isHideout;}
export function choosePower(app,id,choice){if(!canChoosePower(app)||!POWERUPS[id]?.some(p=>p.id===choice))return false;app.settings.powerups={...app.settings.powerups,[id]:choice};app.save.saveSettings(app.settings);return true;}
